package app.kinnect.live;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;

/** Foreground lifetime for screen sharing; never restarts or reuses a projection token. */
public final class LiveGameService extends Service {
 static final String START="live.game.start",STOP="live.game.stop",PAUSE="live.game.pause",MIC="live.game.mic";
 interface Controls{void stop();void pause();void mic();void reply(String text);}
 private Controls controls;private boolean paused,muted;private boolean foregroundStarted=false;private GameCommentOverlay overlay;
 final class SessionBinder extends Binder{LiveGameService service(){return LiveGameService.this;}}
 private final SessionBinder binder=new SessionBinder();
 public IBinder onBind(Intent intent){return binder;}
 public void onCreate(){super.onCreate();NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("live_game","Kinnect Live",NotificationManager.IMPORTANCE_LOW));}
 boolean attach(Controls value){controls=value;if(!refresh()){controls=null;stopSelf();return false;}overlay=new GameCommentOverlay(this,new GameCommentOverlay.Actions(){public void mic(){if(controls!=null)controls.mic();}public void pause(){if(controls!=null)controls.pause();}public void reply(String text){if(controls!=null)controls.reply(text);}public void room(){startActivity(new Intent(LiveGameService.this,LiveActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP));}});return true;}
 void overlayVisible(boolean visible){if(overlay==null)return;if(visible)overlay.show();else overlay.hide();}
 void viewers(int count){if(overlay!=null)overlay.viewers(count);}
 void comment(String name,String text){if(overlay!=null)overlay.comment(name,text);}
 void flags(boolean pause,boolean mute){paused=pause;muted=mute;if(overlay!=null)overlay.flags(pause,mute);refresh();}
 private PendingIntent action(String type,int id){return PendingIntent.getService(this,id,new Intent(this,LiveGameService.class).setAction(type),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private boolean refresh(){Intent open=new Intent(this,LiveActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(this,802,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(this,"live_game").setSmallIcon(android.R.drawable.presence_video_online).setContentTitle(I18n.t("Kinnect · Chơi game trực tiếp")).setContentText(I18n.t(paused?"Đã tạm che màn hình":"Đang chia sẻ màn hình · Chạm để về phòng Live")).setContentIntent(content).setOngoing(true).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_SERVICE).addAction(new Notification.Action.Builder(null,I18n.t(muted?"Bật mic":"Tắt mic"),action(MIC,803)).build()).addAction(new Notification.Action.Builder(null,I18n.t(paused?"Tiếp tục":"Tạm che"),action(PAUSE,804)).build()).addAction(new Notification.Action.Builder(null,I18n.t("Kết thúc"),action(STOP,805)).build()).build();if(foregroundStarted){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(nm!=null)nm.notify(802,notification);return true;}int type=ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION;if(Build.VERSION.SDK_INT>=30&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED&&(Build.VERSION.SDK_INT<34||checkSelfPermission("android.permission.FOREGROUND_SERVICE_MICROPHONE")==android.content.pm.PackageManager.PERMISSION_GRANTED)){try{int declaredType=getPackageManager().getServiceInfo(new ComponentName(this,LiveGameService.class),0).getForegroundServiceType();if((declaredType&ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE)!=0)type|=ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE;}catch(Exception ignored){}}try{if(Build.VERSION.SDK_INT>=29)startForeground(802,notification,type);else startForeground(802,notification);foregroundStarted=true;return true;}catch(Exception e){android.util.Log.w("KinnectLive","LiveGameService startForeground failed: "+e.getMessage());foregroundStarted=false;return false;}}
 public int onStartCommand(Intent intent,int flags,int id){String action=intent==null?"":intent.getAction();if(START.equals(action)){if(!refresh())stopSelf();return START_NOT_STICKY;}if(controls==null){if(foregroundStarted){try{stopForeground(true);}catch(Exception ignored){}foregroundStarted=false;}stopSelf();return START_NOT_STICKY;}if(STOP.equals(action))controls.stop();else if(PAUSE.equals(action))controls.pause();else if(MIC.equals(action))controls.mic();return START_NOT_STICKY;}
 void detach(){foregroundStarted=false;if(overlay!=null)overlay.clear();overlay=null;controls=null;try{stopForeground(true);}catch(Exception ignored){}stopSelf();}
 public void onTaskRemoved(Intent root){if(controls!=null)controls.stop();stopSelf();}
 public void onDestroy(){foregroundStarted=false;if(overlay!=null)overlay.clear();overlay=null;Controls c=controls;controls=null;if(c!=null)c.stop();super.onDestroy();}
}
